    static var ai_notice: String { s(["zh": "⚠️ 译文由 AI 生成，可能有错，发送前请自行核对。", "en": "⚠️ Translations are AI-generated and may be wrong. Check before you send.", "hant": "⚠️ 譯文由 AI 生成，可能有錯，發送前請自行核對。", "ja": "⚠️ 翻訳はAI生成のため誤りがある場合があります。送信前にご確認ください。", "de": "⚠️ Übersetzungen sind KI-generiert und können Fehler enthalten. Prüfe sie vor dem Senden.", "es": "⚠️ Las traducciones son generadas por IA y pueden contener errores. Revísalas antes de enviar.", "ar": "⚠️ الترجمة مولّدة بالذكاء الاصطناعي وقد تحتوي أخطاء. تحقق قبل الإرسال.", "vi": "⚠️ Bản dịch do AI tạo, có thể sai, vui lòng kiểm tra trước khi gửi.", "th": "⚠️ คำแปลสร้างโดย AI อาจมีข้อผิดพลาด โปรดตรวจสอบก่อนส่ง"]) }
