    static var ex_translate: String { s(["zh": "翻译：直接说话，出目标语言的干净短消息。语气和目标语言在下面那排选。", "en": "Translate: just speak, and get a clean short message in the target language. Pick the tone and target language in the row below.", "hant": "翻譯：直接說話，出目標語言的乾淨短消息。語氣和目標語言在下面那排選。", "ja": "翻译：直接说话，出目标语言的干净短消息。语气和目标语言在下面那排选。", "de": "Übersetzen: Sprich einfach, du bekommst eine saubere kurze Nachricht in der Zielsprache. Ton und Zielsprache wählst du in der Reihe darunter.", "es": "Traduce: solo habla y obtén un mensaje corto y limpio en el idioma de destino. Elige el tono y el idioma de destino en la fila de abajo.", "ar": "الترجمة: تحدث فقط، وستحصل على رسالة قصيرة وواضحة باللغة الهدف. اختر النبرة واللغة الهدف في الصف أدناه.", "vi": "Dịch: chỉ cần nói, sẽ có tin nhắn ngắn gọn, sạch sẽ bằng ngôn ngữ đích. Chọn giọng điệu và ngôn ngữ đích ở hàng bên dưới.", "th": "แปล: พูดได้เลย แล้วจะได้ข้อความสั้น ๆ ที่สะอาดในภาษาปลายทาง เลือกโทนและภาษาปลายทางได้ที่แถวด้านล่าง"]) }
    static var ex_transcribe: String { s(["zh": "转写：不翻译，保留你说的那个语言。下面可选「整理」（去口水话、该分点就分点）或「逐字」（一个字不改）。", "en": "Transcribe: no translation — you get back the language you spoke. Below, pick Clean up (drops filler, splits into points where it helps) or Verbatim (nothing changed).", "hant": "轉寫：不翻譯，保留你說的那個語言。下面可選「整理」（去口水話、該分點就分點）或「逐字」（一個字不改）。", "ja": "文字起こし：翻訳せず、話した言語のまま出力。下で「整理」（不要な言葉を削除、必要に応じて箇条書き）または「逐語」（一字も変えない）を選択。", "de": "Transkribieren: Keine Übersetzung – du bekommst die Sprache, die du gesprochen hast. Unten kannst du „Aufräumen“ (entfernt Füllwörter, teilt in Punkte) oder „Wörtlich“ (nichts geändert) wählen.", "es": "Transcribir: sin traducción — recibes el idioma que hablaste. Abajo, elige Limpiar (quita muletillas, divide en puntos donde ayuda) o Textual (sin cambios).", "ar": "نسخ صوتي: بدون ترجمة — تحصل على اللغة التي تحدثت بها. أدناه اختر «تنظيم» (يحذف الحشو ويقسم إلى نقاط عند الحاجة) أو «حرفي» (بدون أي تغيير).", "vi": "Chép lại: không dịch — giữ nguyên ngôn ngữ bạn đã nói. Bên dưới, chọn Sắp xếp (bỏ từ đệm, tách thành các ý khi cần) hoặc Nguyên văn (không thay đổi gì).", "th": "ถอดเสียง: ไม่แปล ได้ภาษาที่คุณพูด ด้านล่างเลือกได้ระหว่าง «จัดระเบียบ» (ตัดคำฟุ่มเฟือย แบ่งเป็นข้อเมื่อเหมาะสม) หรือ «คำต่อคำ» (ไม่แก้แม้แต่คำเดียว)"]) }
    static var ex_history: String { s(["zh": "历史：之前上屏过的内容都在这里，删没了可以回来重新复制。", "en": "History: everything you've inserted lives here — if you delete it, come back and copy it again.", "hant": "歷史：之前上屏過的內容都在這裡，刪沒了可以回來重新複製。", "ja": "履歴：これまでに挿入した内容がすべてここにあります。削除しても、戻って再コピーできます。", "de": "Verlauf: Alles, was du eingefügt hast, ist hier – wenn du es löschst, komm zurück und kopiere es erneut.", "es": "Historial: todo lo que has insertado vive aquí — si lo borras, vuelve y cópialo de nuevo.", "ar": "السجل: كل ما أدخلته موجود هنا — إذا حذفته، عد وانسخه مرة أخرى.", "vi": "Lịch sử: mọi nội dung bạn đã chèn đều ở đây — nếu xóa mất, quay lại và sao chép lại.", "th": "ประวัติ: เนื้อหาที่เคยแทรกทั้งหมดอยู่ที่นี่ ถ้าลบไปแล้วกลับมาคัดลอกใหม่ได้"]) }
    static var ex_polish: String { s(["zh": "整理：滤掉「嗯、那个、就是说」这类口水话，说了几件事就分几条，但不翻译，你说什么语言就出什么语言。", "en": "Clean up: drops filler like um and you know, splits several points into separate lines — but does not translate. You get back the language you spoke.", "hant": "整理：濾掉「嗯、那個、就是說」這類口水話，說了幾件事就分幾條，但不翻譯，你說什麼語言就出什麼語言。", "ja": "整理：”えっと”“あの”“つまり”などのつなぎ言葉を除去し、複数の要点は別々の行に分けます。ただし翻訳はしません。話した言語のまま出力されます。", "de": "Aufräumen: entfernt Füllwörter wie ähm und weißt du, teilt mehrere Punkte in separate Zeilen auf – übersetzt aber nicht. Du bekommst die Sprache zurück, die du gesprochen hast.", "es": "Ordenar: elimina muletillas como este y sabes, divide varios puntos en líneas separadas, pero no traduce. Recibes el idioma que hablaste.", "ar": "تنقية: يحذف كلمات الحشو مثل «امم» و«يعني»، ويقسم النقاط إلى أسطر منفصلة — لكنه لا يترجم. تحصل على اللغة التي تحدثت بها.", "vi": "Sắp xếp: bỏ từ đệm như \"ừm\", \"kiểu như\" — nếu nói nhiều ý thì tách thành từng dòng, nhưng không dịch. Bạn nói ngôn ngữ nào thì nhận lại ngôn ngữ đó.", "th": "จัดระเบียบ: ตัดคำฟุ่มเฟือยอย่าง «อืม» «นั่นแหละ» «คือว่า» ออก พูดกี่เรื่องก็แบ่งเป็นข้อตามนั้น แต่ไม่แปล พูดภาษาไหนก็ได้ภาษานั้น"]) }
    static var ex_verbatim: String { s(["zh": "逐字：听到什么写什么，一个字不改、不整理、不翻译。", "en": "Verbatim: exactly what you said — nothing changed, cleaned up or translated.", "hant": "逐字：聽到什麼寫什麼，一個字不改、不整理、不翻譯。", "ja": "逐語：聞こえたままを書き起こします。一字も変えず、整理も翻訳もしません。", "de": "Wörtlich: Genau was du gesagt hast – nichts geändert, aufgeräumt oder übersetzt.", "es": "Texto literal: exactamente lo que dijiste, sin cambios, sin limpiar ni traducir.", "ar": "حرفي: بالضبط ما قلته — بدون تغيير أو تنظيف أو ترجمة.", "vi": "Nguyên văn: đúng những gì bạn nói — không thay đổi, không sắp xếp, không dịch.", "th": "คำต่อคำ: ได้ยินอะไรก็เขียนอย่างนั้น ไม่แก้แม้แต่คำเดียว ไม่จัดระเบียบ ไม่แปล"]) }
    static var ex_mic: String { s(["zh": "点一下开始说，说完再点一下停。中途停顿思考没关系，不会自动截断。单次最长 %1$@ 秒，最后 %2$@ 秒圆圈里会倒数，到点会自动帮你整理这一段。", "en": "Tap once to start talking, tap again to stop. Pausing to think is fine — it won't cut you off. Up to %1$@ seconds per take; the last %2$@ seconds count down inside the circle, and it wraps up on its own at the end.", "hant": "點一下開始說，說完再點一下停。中途停頓思考沒關係，不會自動截斷。單次最長 %1$@ 秒，最後 %2$@ 秒圓圈裡會倒數，到點會自動幫你整理這一段。", "ja": "タップして話し始め、もう一度タップして停止。考え中の間も自動で切れません。1回あたり最大%1$@秒、最後の%2$@秒は円の中でカウントダウンされ、時間になると自動でこの部分を整理します。", "de": "Tippe einmal, um zu sprechen, tippe erneut, um zu stoppen. Pausen zum Nachdenken sind okay – es schneidet dich nicht ab. Bis zu %1$@ Sekunden pro Aufnahme; die letzten %2$@ Sekunden zählen im Kreis herunter, und es beendet automatisch.", "es": "Toca para empezar a hablar, toca de nuevo para detener. Pausar para pensar está bien: no te corta. Hasta %1$@ segundos por toma; los últimos %2$@ segundos cuentan regresivamente dentro del círculo y se envuelve solo al final.", "ar": "اضغط مرة لبدء التحدث، واضغط مرة أخرى للتوقف. التوقف للتفكير لا بأس به — لن يقطعك. حتى ‎%1$@‎ ثانية لكل جلسة؛ آخر ‎%2$@‎ ثوانٍ تُعد تنازليًا داخل الدائرة، وينتهي تلقائيًا في النهاية.", "vi": "Nhấn một lần để bắt đầu nói, nhấn lần nữa để dừng. Dừng lại để suy nghĩ không sao — sẽ không tự cắt. Tối đa %1$@ giây mỗi lần; %2$@ giây cuối sẽ đếm ngược trong vòng tròn, và tự động kết thúc khi hết giờ.", "th": "แตะหนึ่งครั้งเพื่อเริ่มพูด แตะอีกครั้งเพื่อหยุด หยุดคิดกลางทางได้ ไม่ตัดให้อัตโนมัติ สูงสุด %1$@ วินาทีต่อครั้ง %2$@ วินาทีสุดท้ายจะมีนับถอยหลังในวงกลม ครบเวลาระบบจะจัดระเบียบให้เอง"]) }
    static var ex_type: String { s(["zh": "打字：内置键盘，拼音/五笔/英文/手写四档，用来改错字。不会把你切到别的输入法。", "en": "Type: the built-in keyboard — Pinyin, Wubi, English and handwriting — for fixing a wrong character. It never switches you to another keyboard.", "hant": "打字：內置鍵盤，拼音/五筆/英文/手寫四檔，用來改錯字。不會把你切到別的輸入法。", "ja": "タイプ：内蔵キーボード（ピンイン、五筆、英語、手書きの4モード）で誤字を修正。他のキーボードに切り替わることはありません。", "de": "Tippen: Die eingebaute Tastatur – Pinyin, Wubi, Englisch und Handschrift – zum Korrigieren eines falschen Zeichens. Sie wechselt dich nie zu einer anderen Tastatur.", "es": "Escribir: el teclado integrado — pinyin, wubi, inglés y escritura a mano — para corregir un carácter equivocado. Nunca te cambia a otro teclado.", "ar": "كتابة: لوحة المفاتيح المدمجة — بينيين، ووبي، والإنجليزية، والكتابة اليدوية — لتصحيح حرف خاطئ. لا يحولك أبدًا إلى لوحة مفاتيح أخرى.", "vi": "Gõ: bàn phím tích hợp — Pinyin, Wubi, tiếng Anh và viết tay — để sửa lỗi chính tả. Không bao giờ chuyển bạn sang bàn phím khác.", "th": "พิมพ์: คีย์บอร์ดในตัว มีพินอิน/อู๋ปี่/อังกฤษ/เขียนมือ ไว้แก้คำผิด ไม่สลับไปคีย์บอร์ดอื่นให้"]) }
    static var ex_speak: String { s(["zh": "朗读：把刚上屏的那段念出来，按语言自动挑音色。", "en": "Read aloud: plays back what was just inserted, with a voice picked to match the language.", "hant": "朗讀：把剛上屏的那段念出來，按語言自動挑音色。", "ja": "読み上げ：入力したばかりの文章を読み上げます。言語に合わせて音声を自動選択します。", "de": "Vorlesen: Spielt das gerade Eingefügte mit einer zur Sprache passenden Stimme ab.", "es": "Leer en voz alta: reproduce lo que se acaba de insertar, con una voz elegida según el idioma.", "ar": "القراءة بصوت عالٍ: تشغيل ما تم إدراجه للتو، مع اختيار صوت يتناسب مع اللغة.", "vi": "Đọc to: phát lại nội dung vừa chèn, với giọng đọc tự chọn theo ngôn ngữ.", "th": "อ่านออกเสียง: อ่านข้อความที่เพิ่งแทรก เลือกเสียงตามภาษาอัตโนมัติ"]) }
    static var ex_backspace: String { s(["zh": "退格：点一下删一个字，长按连删，1.2 秒后按词删。有选中就整段删。", "en": "Backspace: one tap deletes one character; hold to repeat, and after 1.2 seconds it deletes whole words. If something is selected, it goes all at once.", "hant": "退格：點一下刪一個字，長按連刪，1.2 秒後按詞刪。有選中就整段刪。", "ja": "バックスペース：1回タップで1文字削除、長押しで連続削除、1.2秒後は単語単位で削除。選択中は一括削除。", "de": "Rücktaste: Ein Tippen löscht ein Zeichen; gedrückt halten wiederholt, und nach 1,2 Sekunden löscht es ganze Wörter. Wenn etwas ausgewählt ist, wird alles auf einmal gelöscht.", "es": "Retroceso: un toque borra un carácter; mantén pulsado para repetir, y después de 1,2 segundos borra palabras completas. Si hay algo seleccionado, se borra todo de una vez.", "ar": "مسافة للخلف: نقرة تحذف حرفًا، والضغط المطول يحذف بشكل متكرر، وبعد ‎1.2‎ ثانية يحذف كلمات كاملة. إذا كان هناك تحديد، يُحذف كله دفعة واحدة.", "vi": "Xóa lùi: nhấn một lần xóa một ký tự; giữ để lặp lại, sau 1,2 giây sẽ xóa cả từ. Nếu có vùng chọn, xóa toàn bộ một lần.", "th": "ลบ: แตะหนึ่งครั้งลบหนึ่งตัวอักษร กดค้างลบต่อเนื่อง หลัง 1.2 วินาทีจะลบเป็นคำ ถ้ามีข้อความเลือกไว้จะลบทั้งช่วง"]) }
    static var ex_send: String { s(["zh": "发送：相当于按输入框右边那个发送键。个别 App 不支持时，会退回按一下回车。", "en": "Send: same as tapping the send button in the app. Where that isn't supported, it falls back to pressing Enter.", "hant": "發送：相當於按輸入框右邊那個發送鍵。個別 App 不支援時，會退回按一下回車。", "ja": "送信：アプリの送信ボタンをタップするのと同じ。非対応のアプリではEnterキーを押す動作にフォールバック。", "de": "Senden: wie das Tippen auf die Senden-Taste in der App. Wo das nicht unterstützt wird, fällt es auf das Drücken der Eingabetaste zurück.", "es": "Enviar: igual que tocar el botón de enviar en la app. Si no es compatible, se reduce a pulsar Intro.", "ar": "إرسال: مثل الضغط على زر الإرسال في التطبيق. إذا لم يكن مدعومًا، يتراجع إلى الضغط على ‎Enter‎.", "vi": "Gửi: giống như nhấn nút gửi trong ứng dụng. Ở nơi không hỗ trợ, sẽ chuyển sang nhấn Enter.", "th": "ส่ง: เทียบเท่ากับกดปุ่มส่งทางขวาของช่องพิมพ์ หากแอปใดไม่รองรับ จะกลับไปใช้การกด Enter แทน"]) }
    static var ex_tone_casual: String { s(["zh": "随意：熟人之间的口气，短、放松，可以用缩写。", "en": "Casual: how you'd talk to someone you know — short, relaxed, contractions are fine.", "hant": "隨意：熟人之間的口氣，短、放鬆，可以用縮寫。", "ja": "カジュアル：知り合いへの話し方——短く、リラックス、省略形もOK。", "de": "Locker: wie du mit jemandem redest, den du kennst – kurz, entspannt, Abkürzungen sind okay.", "es": "Casual: como hablarías con alguien conocido: breve, relajado, se permiten contracciones.", "ar": "غير رسمي: أسلوب الحديث مع معارفك — قصير، مريح، ويسمح بالاختصارات.", "vi": "Thoải mái: cách bạn nói với người quen — ngắn, nhẹ nhàng, có thể dùng từ viết tắt.", "th": "กันเอง: น้ำเสียงแบบคนรู้จัก สั้น ผ่อนคลาย ใช้คำย่อได้"]) }
    static var ex_tone_work: String { s(["zh": "工作：发给同事或对接人的直接消息（Slack / 微信 / Teams），专业但不端着。", "en": "Work: a direct message to a colleague or counterpart (Slack, WeChat, Teams) — professional without being stiff.", "hant": "工作：發給同事或對接人的直接消息（Slack / 微信 / Teams），專業但不端著。", "ja": "仕事：同僚や取引先への直接メッセージ（Slack／WeChat／Teams）——堅苦しくなくプロフェッショナルに。", "de": "Arbeit: eine direkte Nachricht an einen Kollegen oder Ansprechpartner (Slack, WeChat, Teams) – professionell, aber nicht steif.", "es": "Trabajo: un mensaje directo a un colega o interlocutor (Slack, WeChat, Teams): profesional sin ser rígido.", "ar": "عمل: رسالة مباشرة لزميل أو جهة تواصل (‎Slack / WeChat / Teams‎) — احترافية دون تكلف.", "vi": "Công việc: tin nhắn trực tiếp cho đồng nghiệp hoặc đối tác (Slack, WeChat, Teams) — chuyên nghiệp nhưng không cứng nhắc.", "th": "งาน: ข้อความตรงถึงเพื่อนร่วมงานหรือผู้ติดต่อ (Slack / WeChat / Teams) เป็นมืออาชีพแต่ไม่แข็ง"]) }
    static var ex_tone_email: String { s(["zh": "邮件：邮件正文，也用于给客户、监管、审计的正式书面沟通。完整句子、措辞精确，不加称呼和落款（除非你自己说了）。", "en": "Email: the body of an email, and formal written contact with clients, regulators or auditors. Full sentences, precise wording, no greeting or sign-off unless you said one.", "hant": "郵件：郵件正文，也用於給客戶、監管、審計的正式書面溝通。完整句子、措辭精確，不加稱呼和落款（除非你自己說了）。", "ja": "メール：メール本文、および顧客・規制当局・監査人への正式な文書連絡。完全な文、正確な表現。挨拶や署名は含めない（自分で指定しない限り）。", "de": "E-Mail: der Text einer E-Mail und formelle schriftliche Kommunikation mit Kunden, Aufsichtsbehörden oder Prüfern. Vollständige Sätze, präzise Formulierungen, keine Anrede oder Grußformel, außer du hast eine genannt.", "es": "Correo: el cuerpo de un correo y contacto formal con clientes, reguladores o auditores. Frases completas, redacción precisa, sin saludo ni despedida a menos que tú lo hayas dicho.", "ar": "بريد إلكتروني: نص البريد، وتواصل رسمي مع العملاء أو الجهات التنظيمية أو المدققين. جمل كاملة، وصياغة دقيقة، دون تحية أو توقيع إلا إذا أضفتها.", "vi": "Email: nội dung email, cũng dùng cho liên lạc chính thức với khách hàng, cơ quan quản lý hoặc kiểm toán. Câu đầy đủ, từ ngữ chính xác, không có lời chào hay ký tên (trừ khi bạn tự nói).", "th": "อีเมล: เนื้อความอีเมล ใช้กับลูกค้า หน่วยงานกำกับดูแล หรือผู้ตรวจสอบด้วย ประโยคครบถ้วน ถ้อยคำแม่นยำ ไม่ใส่คำขึ้นต้นและลงท้าย (เว้นแต่คุณพูดเอง)"]) }
    static var ex_mic_ios: String { s(["zh": "点一下开始说，说完再点一下停。中途停顿思考没关系，不会自动截断。", "en": "Tap once to start talking, tap again to stop. Pausing to think is fine — it won't cut you off.", "hant": "點一下開始說，說完再點一下停。中途停頓思考沒關係，不會自動截斷。", "ja": "タップで話し始め、もう一度タップで停止。考え中の間は自動で切れないので大丈夫。", "de": "Tippe einmal, um zu sprechen, tippe erneut, um zu stoppen. Eine Pause zum Nachdenken ist in Ordnung – es bricht nicht ab.", "es": "Toca una vez para empezar a hablar, toca de nuevo para detener. Hacer una pausa para pensar está bien: no te cortará.", "ar": "اضغط مرة للبدء في التحدث، واضغط مرة أخرى للتوقف. التوقف للتفكير لا بأس به — لن يقطعك.", "vi": "Nhấn một lần để bắt đầu nói, nhấn lần nữa để dừng. Dừng lại để suy nghĩ không sao — sẽ không tự cắt.", "th": "แตะหนึ่งครั้งเพื่อเริ่มพูด แตะอีกครั้งเพื่อหยุด หยุดคิดกลางทางได้ ไม่ตัดให้อัตโนมัติ"]) }
